CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "World" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "World_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Center" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'sleeping', "worldId" TEXT NOT NULL, CONSTRAINT "Center_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Task" ("id" TEXT NOT NULL, "centerId" TEXT NOT NULL, "title" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'queued', "input" JSONB, "output" JSONB, "approvedInput" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Task_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Approval" ("id" TEXT NOT NULL, "centerId" TEXT NOT NULL, "taskId" TEXT, "kind" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "payload" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolvedAt" TIMESTAMP(3), CONSTRAINT "Approval_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Event" ("id" TEXT NOT NULL, "centerId" TEXT NOT NULL, "type" TEXT NOT NULL, "message" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Event_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Video" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'draft', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Video_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Asset" ("id" TEXT NOT NULL, "videoId" TEXT NOT NULL, "platform" TEXT NOT NULL, "key" TEXT, "status" TEXT NOT NULL DEFAULT 'mock', "aspectRatio" TEXT NOT NULL DEFAULT '9:16', "durationSeconds" INTEGER, CONSTRAINT "Asset_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Publication" ("id" TEXT NOT NULL, "videoId" TEXT NOT NULL, "platform" TEXT NOT NULL, "mode" TEXT NOT NULL DEFAULT 'mock', "status" TEXT NOT NULL DEFAULT 'queued', "scheduledAt" TIMESTAMP(3), "platformId" TEXT, "error" TEXT, CONSTRAINT "Publication_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlatformConnection" ("id" TEXT NOT NULL, "platform" TEXT NOT NULL, "mode" TEXT NOT NULL DEFAULT 'mock', "encryptedTokens" TEXT, "lastError" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PlatformConnection_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PlatformConnection_platform_key" ON "PlatformConnection"("platform");
CREATE TABLE "Setting" ("key" TEXT NOT NULL, "value" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Setting_pkey" PRIMARY KEY ("key"));
ALTER TABLE "Center" ADD CONSTRAINT "Center_worldId_fkey" FOREIGN KEY ("worldId") REFERENCES "World"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_centerId_fkey" FOREIGN KEY ("centerId") REFERENCES "Center"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Approval" ADD CONSTRAINT "Approval_centerId_fkey" FOREIGN KEY ("centerId") REFERENCES "Center"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Event" ADD CONSTRAINT "Event_centerId_fkey" FOREIGN KEY ("centerId") REFERENCES "Center"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Asset" ADD CONSTRAINT "Asset_videoId_fkey" FOREIGN KEY ("videoId") REFERENCES "Video"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Publication" ADD CONSTRAINT "Publication_videoId_fkey" FOREIGN KEY ("videoId") REFERENCES "Video"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
